package com.wedo.backend.moment;

import static com.wedo.backend.moment.MomentDtos.*;
import com.wedo.backend.common.error.*;
import com.wedo.backend.group.entity.*;
import com.wedo.backend.group.service.GroupPermissionService;
import com.wedo.backend.media.dto.*;
import com.wedo.backend.media.service.MediaReferenceService;
import com.wedo.backend.media.storage.ObjectStorageService;
import com.wedo.backend.realtime.RealtimePublisher;
import java.sql.*;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Transactional(readOnly=true)
public class MomentService {
 private final JdbcTemplate db;
 private final GroupPermissionService groups;
 private final MediaReferenceService refs;
 private final ObjectStorageService storage;
 private final RealtimePublisher realtime;
 public MomentService(JdbcTemplate db,GroupPermissionService groups,MediaReferenceService refs,ObjectStorageService storage,RealtimePublisher realtime){this.db=db;this.groups=groups;this.refs=refs;this.storage=storage;this.realtime=realtime;}
 private BusinessException missing(){return new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);}
 private BusinessException invalid(){return new BusinessException(ErrorCode.VALIDATION_FAILED);}
 private Map<String,Object> row(String sql,Object...args){var rows=db.queryForList(sql,args);if(rows.isEmpty())throw missing();return rows.getFirst();}
 private UUID id(Map<String,Object> r,String key){return (UUID)r.get(key);}
 private Instant at(Map<String,Object> r,String key){return ((Timestamp)r.get(key)).toInstant();}
 private void activity(UUID group,UUID activity){if(activity!=null&&!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM activities WHERE id=? AND group_id=?)",Boolean.class,activity,group)))throw missing();}
 private boolean manage(UUID group,UUID actor,UUID author){var a=groups.requireReadableMembership(group,actor);return actor.equals(author)||a.membership().getRole()!=GroupRole.MEMBER;}
 private boolean writable(UUID group,UUID actor){return groups.requireReadableMembership(group,actor).group().getStatus()==GroupStatus.ACTIVE;}
 private Author author(UUID user){return db.queryForObject("SELECT id,COALESCE(display_name,username::text,'Người dùng') AS name,avatar_storage_key FROM users WHERE id=?",(r,n)->new Author(r.getObject("id",UUID.class),r.getString("name"),r.getString("avatar_storage_key")),user);}
 private String activityTitle(UUID activity){return activity==null?null:db.queryForObject("SELECT title FROM activities WHERE id=?",String.class,activity);}
 private Media media(ResultSet r,int n)throws SQLException{return new Media(r.getObject("id",UUID.class),r.getString("content_type"),r.getString("file_name"),r.getLong("file_size"),r.getInt("sort_order"));}
 private Map<String,Object> momentRow(UUID moment,UUID actor,boolean lock){var r=row("SELECT * FROM group_moments WHERE id=? AND deleted_at IS NULL"+(lock?" FOR UPDATE":""),moment);if(lock)groups.requireMutableMembership(id(r,"group_id"),actor);else groups.requireReadableMembership(id(r,"group_id"),actor);return r;}
 private Map<String,Object> albumRow(UUID album,UUID actor,boolean lock){var r=row("SELECT * FROM group_albums WHERE id=? AND deleted_at IS NULL"+(lock?" FOR UPDATE":""),album);if(lock)groups.requireMutableMembership(id(r,"group_id"),actor);else groups.requireReadableMembership(id(r,"group_id"),actor);return r;}
 private void own(Map<String,Object> r,UUID actor){if(!manage(id(r,"group_id"),actor,id(r,"created_by")))throw new BusinessException(ErrorCode.ACCESS_DENIED);}
 private void emit(String type,UUID resource,UUID group){realtime.resource(type,type.startsWith("ALBUM_")?"ALBUM":"MOMENT",resource,"group:"+group,group,null);}
 public Moment get(UUID moment,UUID actor){var r=momentRow(moment,actor,false);UUID group=id(r,"group_id"),creator=id(r,"created_by");boolean edit=writable(group,actor)&&manage(group,actor,creator);return new Moment(moment,group,id(r,"activity_id"),activityTitle(id(r,"activity_id")),author(creator),(String)r.get("caption"),at(r,"created_at"),at(r,"updated_at"),db.query("SELECT * FROM moment_media WHERE moment_id=? ORDER BY sort_order,id",this::media,moment),db.queryForObject("SELECT count(*) FROM moment_reactions WHERE moment_id=?",Long.class,moment),db.query("SELECT emoji FROM moment_reactions WHERE moment_id=? AND user_id=?",rs->rs.next()?rs.getString(1):null,moment,actor),db.queryForObject("SELECT count(*) FROM moment_comments WHERE moment_id=? AND deleted_at IS NULL",Long.class,moment),new Permissions(edit,edit,writable(group,actor),edit));}
 public Page<Moment> feed(UUID group,UUID actor,UUID activity,UUID before){groups.requireReadableMembership(group,actor);activity(group,activity);var ids=db.queryForList("SELECT id FROM group_moments WHERE group_id=? AND deleted_at IS NULL AND (?::uuid IS NULL OR activity_id=?) AND (?::uuid IS NULL OR (created_at,id)<(SELECT created_at,id FROM group_moments WHERE id=? AND group_id=?)) ORDER BY created_at DESC,id DESC LIMIT 21",UUID.class,group,activity,activity,before,before,group);return new Page<>(ids.stream().limit(20).map(i->get(i,actor)).toList(),ids.size()>20?ids.get(19):null,ids.size()>20,writable(group,actor));}
 @Transactional public Moment create(UUID group,UUID actor,CreateMoment request){groups.requireMutableMembership(group,actor);activity(group,request.activityId());if(request.caption().trim().isEmpty()&&request.mediaKeys().isEmpty())throw invalid();if(request.mediaKeys().size()>8||new HashSet<>(request.mediaKeys()).size()!=request.mediaKeys().size())throw invalid();
  var existing=db.queryForList("SELECT group_id,created_by FROM group_moments WHERE id=?",request.clientRequestId());if(!existing.isEmpty()){if(!group.equals(id(existing.getFirst(),"group_id"))||!actor.equals(id(existing.getFirst(),"created_by")))throw invalid();return get(request.clientRequestId(),actor);}
  int inserted=db.update("INSERT INTO group_moments(id,group_id,activity_id,created_by,caption) VALUES (?,?,?,?,?) ON CONFLICT(id) DO NOTHING",request.clientRequestId(),group,request.activityId(),actor,request.caption().trim());
  if(inserted==0){var previous=momentRow(request.clientRequestId(),actor,false);if(!group.equals(id(previous,"group_id"))||!actor.equals(id(previous,"created_by")))throw invalid();return get(request.clientRequestId(),actor);}
  for(String key:request.mediaKeys()){var parsed=refs.parse(key);if(parsed==null||!(parsed.category()==UploadCategory.MOMENT_IMAGE||parsed.category()==UploadCategory.MOMENT_VIDEO))throw invalid();refs.validate(key,parsed.category(),group,actor);if(Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM moment_media WHERE storage_key=?)",Boolean.class,key)))throw invalid();}
  int order=0;for(String key:request.mediaKeys()){var h=storage.head(key);db.update("INSERT INTO moment_media(id,moment_id,storage_key,content_type,file_name,file_size,sort_order) VALUES (?,?,?,?,?,?,?)",UUID.randomUUID(),request.clientRequestId(),key,h.contentType(),refs.originalFileName(key),h.size(),order++);}
  emit("MOMENT_CREATED",request.clientRequestId(),group);return get(request.clientRequestId(),actor);
 }
 @Transactional public Moment edit(UUID moment,UUID actor,EditMoment request){var r=momentRow(moment,actor,true);own(r,actor);activity(id(r,"group_id"),request.activityId());if(!Objects.equals(id(r,"activity_id"),request.activityId())&&db.queryForObject("SELECT count(*) FROM activity_stop_checkins WHERE moment_id=?",Integer.class,moment)>0)throw invalid();if(request.caption().trim().isEmpty()&&get(moment,actor).media().isEmpty())throw invalid();db.update("UPDATE group_moments SET caption=?,activity_id=?,updated_at=now() WHERE id=?",request.caption().trim(),request.activityId(),moment);emit("MOMENT_UPDATED",moment,id(r,"group_id"));return get(moment,actor);}
 @Transactional public void delete(UUID moment,UUID actor){var r=momentRow(moment,actor,true);own(r,actor);db.update("UPDATE group_moments SET deleted_at=now(),deleted_by=? WHERE id=?",actor,moment);emit("MOMENT_DELETED",moment,id(r,"group_id"));for(UUID album:db.queryForList("SELECT DISTINCT ai.album_id FROM album_items ai JOIN moment_media mm ON mm.id=ai.media_id WHERE mm.moment_id=?",UUID.class,moment))emit("ALBUM_UPDATED",album,id(r,"group_id"));}
 @Transactional public Moment react(UUID moment,UUID actor,String emoji){var r=momentRow(moment,actor,true);if(emoji!=null&&!Set.of("👍","❤️","😂","😮","😢","😡").contains(emoji))throw invalid();int changed=emoji==null?db.update("DELETE FROM moment_reactions WHERE moment_id=? AND user_id=?",moment,actor):db.update("INSERT INTO moment_reactions(moment_id,user_id,emoji) VALUES (?,?,?) ON CONFLICT(moment_id,user_id) DO UPDATE SET emoji=excluded.emoji WHERE moment_reactions.emoji IS DISTINCT FROM excluded.emoji",moment,actor,emoji);if(changed>0)emit("MOMENT_REACTION_CHANGED",moment,id(r,"group_id"));return get(moment,actor);}
 private Comment comment(Map<String,Object> r,UUID actor,Map<String,Object> parent){return new Comment(id(r,"id"),author(id(r,"created_by")),(String)r.get("content"),at(r,"created_at"),writable(id(parent,"group_id"),actor)&&manage(id(parent,"group_id"),actor,id(r,"created_by")));}
 public Page<Comment> comments(UUID moment,UUID actor,UUID before){var parent=momentRow(moment,actor,false);var rows=db.queryForList("SELECT * FROM moment_comments WHERE moment_id=? AND deleted_at IS NULL AND (?::uuid IS NULL OR (created_at,id)<(SELECT created_at,id FROM moment_comments WHERE id=? AND moment_id=?)) ORDER BY created_at DESC,id DESC LIMIT 21",moment,before,before,moment);return new Page<>(rows.stream().limit(20).map(r->comment(r,actor,parent)).toList(),rows.size()>20?id(rows.get(19),"id"):null,rows.size()>20);}
 @Transactional public Comment addComment(UUID moment,UUID actor,AddComment request){var p=momentRow(moment,actor,true);int inserted=db.update("INSERT INTO moment_comments(id,moment_id,created_by,content) VALUES (?,?,?,?) ON CONFLICT(id) DO NOTHING",request.clientRequestId(),moment,actor,request.content().trim());var r=row("SELECT * FROM moment_comments WHERE id=? AND deleted_at IS NULL",request.clientRequestId());if(!actor.equals(id(r,"created_by"))||!moment.equals(id(r,"moment_id")))throw invalid();if(inserted>0)emit("MOMENT_COMMENT_CHANGED",moment,id(p,"group_id"));return comment(r,actor,p);}
 @Transactional public void deleteComment(UUID moment,UUID comment,UUID actor){var p=momentRow(moment,actor,true);var r=row("SELECT * FROM moment_comments WHERE id=? AND moment_id=? AND deleted_at IS NULL",comment,moment);if(!manage(id(p,"group_id"),actor,id(r,"created_by")))throw new BusinessException(ErrorCode.ACCESS_DENIED);db.update("UPDATE moment_comments SET deleted_at=now(),deleted_by=? WHERE id=?",actor,comment);emit("MOMENT_COMMENT_CHANGED",moment,id(p,"group_id"));}
 public Album album(UUID album,UUID actor){var r=albumRow(album,actor,false);UUID group=id(r,"group_id"),creator=id(r,"created_by");boolean edit=writable(group,actor)&&manage(group,actor,creator);var cover=db.query("SELECT mm.* FROM album_items ai JOIN moment_media mm ON mm.id=ai.media_id JOIN group_moments m ON m.id=mm.moment_id AND m.deleted_at IS NULL WHERE ai.album_id=? ORDER BY CASE WHEN mm.content_type LIKE 'image/%' THEN 0 ELSE 1 END,ai.added_at,mm.id LIMIT 1",this::media,album);long count=db.queryForObject("SELECT count(*) FROM album_items ai JOIN moment_media mm ON mm.id=ai.media_id JOIN group_moments m ON m.id=mm.moment_id AND m.deleted_at IS NULL WHERE ai.album_id=?",Long.class,album);return new Album(album,group,id(r,"activity_id"),activityTitle(id(r,"activity_id")),(String)r.get("name"),(String)r.get("description"),author(creator),at(r,"created_at"),count,cover.isEmpty()?null:cover.getFirst(),new Permissions(edit,edit,writable(group,actor),edit));}
 public Page<Album> albums(UUID group,UUID actor,UUID activity,UUID before){groups.requireReadableMembership(group,actor);activity(group,activity);var ids=db.queryForList("SELECT id FROM group_albums WHERE group_id=? AND deleted_at IS NULL AND (?::uuid IS NULL OR activity_id=?) AND (?::uuid IS NULL OR (created_at,id)<(SELECT created_at,id FROM group_albums WHERE id=? AND group_id=?)) ORDER BY created_at DESC,id DESC LIMIT 21",UUID.class,group,activity,activity,before,before,group);return new Page<>(ids.stream().limit(20).map(i->album(i,actor)).toList(),ids.size()>20?ids.get(19):null,ids.size()>20,writable(group,actor));}
 @Transactional public Album saveAlbum(UUID group,UUID actor,SaveAlbum request,boolean update){groups.requireMutableMembership(group,actor);activity(group,request.activityId());if(update){var r=albumRow(request.clientRequestId(),actor,true);if(!group.equals(id(r,"group_id")))throw missing();own(r,actor);db.update("UPDATE group_albums SET name=?,description=?,activity_id=?,updated_at=now() WHERE id=?",request.name().trim(),Objects.requireNonNullElse(request.description(),""),request.activityId(),request.clientRequestId());}
  else{int inserted=db.update("INSERT INTO group_albums(id,group_id,activity_id,created_by,name,description) VALUES (?,?,?,?,?,?) ON CONFLICT(id) DO NOTHING",request.clientRequestId(),group,request.activityId(),actor,request.name().trim(),Objects.requireNonNullElse(request.description(),""));if(inserted==0){var r=albumRow(request.clientRequestId(),actor,false);if(!group.equals(id(r,"group_id"))||!actor.equals(id(r,"created_by")))throw invalid();return album(request.clientRequestId(),actor);}}
  emit(update?"ALBUM_UPDATED":"ALBUM_CREATED",request.clientRequestId(),group);return album(request.clientRequestId(),actor);
 }
 @Transactional public void deleteAlbum(UUID album,UUID actor){var r=albumRow(album,actor,true);own(r,actor);db.update("UPDATE group_albums SET deleted_at=now(),deleted_by=? WHERE id=?",actor,album);emit("ALBUM_DELETED",album,id(r,"group_id"));}
 @Transactional public Album items(UUID album,UUID actor,List<UUID> media,boolean add){var r=albumRow(album,actor,true);own(r,actor);int changed=0;for(UUID mediaId:new HashSet<>(media)){var owner=row("SELECT m.group_id FROM moment_media mm JOIN group_moments m ON m.id=mm.moment_id AND m.deleted_at IS NULL WHERE mm.id=?",mediaId);if(!id(r,"group_id").equals(id(owner,"group_id")))throw missing();changed+=add?db.update("INSERT INTO album_items(album_id,media_id,added_by) VALUES (?,?,?) ON CONFLICT DO NOTHING",album,mediaId,actor):db.update("DELETE FROM album_items WHERE album_id=? AND media_id=?",album,mediaId);}if(changed>0)emit("ALBUM_UPDATED",album,id(r,"group_id"));return album(album,actor);}
 public Page<Media> albumMedia(UUID album,UUID actor,UUID before){albumRow(album,actor,false);var all=db.query("SELECT mm.* FROM album_items ai JOIN moment_media mm ON mm.id=ai.media_id JOIN group_moments m ON m.id=mm.moment_id AND m.deleted_at IS NULL WHERE ai.album_id=? AND (?::uuid IS NULL OR mm.id<?) ORDER BY mm.id DESC LIMIT 41",this::media,album,before,before);return new Page<>(all.stream().limit(40).toList(),all.size()>40?all.get(39).id():null,all.size()>40);}
 public MediaAccessResponse mediaAccess(UUID media,UUID actor){var r=row("SELECT mm.storage_key,m.id AS moment FROM moment_media mm JOIN group_moments m ON m.id=mm.moment_id AND m.deleted_at IS NULL WHERE mm.id=?",media);momentRow(id(r,"moment"),actor,false);var target=storage.presignGet((String)r.get("storage_key"),Duration.ofSeconds(60));return new MediaAccessResponse(target.url(),target.expiresAt());}
}
